sys_script.script:
(function executeRule(current, previous) {

    var COMPANY_TABLE =
        'x_snc_college_pl_0_company';

    var APPROVAL_TABLE =
        'x_snc_college_pl_0_offer_letter_approval';

    // Get company from the newly created offer
    var companyId =
        current.getValue('company');

    if (!companyId) {
        return;
    }

    // Get company record
    var companyGR =
        new GlideRecord(COMPANY_TABLE);

    if (!companyGR.get(companyId)) {
        return;
    }

    // Get the company's HR / Interviewer
    var hrUser =
        companyGR.getValue('hr_user');

    if (!hrUser) {
        return;
    }

    // Prevent duplicate approval records
    var existingGR =
        new GlideRecord(APPROVAL_TABLE);

    existingGR.addQuery(
        'offer_letter',
        current.getUniqueValue()
    );

    existingGR.addQuery(
        'hr_user',
        hrUser
    );

    existingGR.setLimit(1);
    existingGR.query();

    if (existingGR.next()) {
        return;
    }

    // Create approval record
    var approvalGR =
        new GlideRecord(APPROVAL_TABLE);

    approvalGR.initialize();

    approvalGR.setValue(
        'offer_letter',
        current.getUniqueValue()
    );

    approvalGR.setValue(
        'hr_user',
        hrUser
    );

    approvalGR.setValue(
        'decision',
        'pending'
    );

    approvalGR.insert();

})(current, previous);
